def get_root_collections(account_id, include_deleted=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_root_collections"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        path2 = os.path.join(_DB, "usage.json")
        if not os.path.exists(path2):
            _save("usage.json", [])

    def _log(status, used_credential=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        row = {
            "id": "rnd_req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential": used_credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

        usage = _load("usage.json")
        day = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d")
        u = None
        for r in usage:
            if r.get("account_id") == (account_id if isinstance(account_id, str) else None) and r.get("date") == day:
                u = r
                break
        if u is None:
            u = {"account_id": account_id if isinstance(account_id, str) else None, "date": day, "requests": 0}
            usage.append(u)
        u["requests"] = int(u.get("requests") or 0) + 1
        _save("usage.json", usage)

    def _rate_limit_ok():
        _ensure_logs()
        logs = _load("request_logs.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        acct = account_id if isinstance(account_id, str) else None
        window_s = 60
        limit_per_min = 120
        cnt = 0
        for r in logs[-5000:]:
            if r.get("account_id") != acct:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                rt = datetime.datetime.fromisoformat(ts)
                if rt.tzinfo is None:
                    rt = rt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if (now - rt).total_seconds() <= window_s:
                cnt += 1
        if cnt >= limit_per_min:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok, e = _rate_limit_ok()
    if not ok:
        _log("error", meta={"error": e})
        return e

    if not isinstance(account_id, str) or not re.match(r"^rnd_acct_[0-9A-Z]{26}$", account_id):
        e = _err("VALIDATION_ERROR", "account_id is missing or invalid", field="account_id")
        _log("error", meta={"error": e})
        return e
    if include_deleted is not None and not isinstance(include_deleted, bool):
        e = _err("VALIDATION_ERROR", "include_deleted must be a boolean", field="include_deleted")
        _log("error", meta={"error": e})
        return e
    if sort is None:
        sort = "sort_order"
    if order is None:
        order = "asc"
    if not isinstance(sort, str) or sort not in ("sort_order", "title", "created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "sort is invalid", field="sort")
        _log("error", meta={"error": e})
        return e
    if not isinstance(order, str) or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order is invalid", field="order")
        _log("error", meta={"error": e})
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit out of range", field="limit", minimum=1, maximum=200)
        _log("error", meta={"error": e})
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        _log("error", meta={"error": e})
        return e

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "Not authorized for this account")
        _log("error", meta={"error": e})
        return e

    cols = _load("collections.json")
    rows = [c for c in cols if c.get("account_id") == account_id and c.get("parent_id") is None]
    if not include_deleted:
        rows = [c for c in rows if c.get("status") == "active"]

    rev = (order == "desc")

    def _sort_key(c):
        v = c.get(sort)
        if sort in ("created_at", "updated_at"):
            if isinstance(v, str):
                try:
                    dt = datetime.datetime.fromisoformat(v)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    return dt.timestamp()
                except Exception:
                    return 0
            return 0
        if sort == "sort_order":
            try:
                return int(v)
            except Exception:
                return 0
        if sort == "title":
            return (v or "").lower()
        return v

    rows.sort(key=lambda c: (_sort_key(c), c.get("created_at") or "", c.get("id") or ""), reverse=rev)

    start = 0
    if cursor:
        # cursor is opaque; implement as base64url of integer offset with checksum
        try:
            raw = cursor.encode("utf-8")
            pad = b"=" * ((4 - (len(raw) % 4)) % 4)
            dec = base64.urlsafe_b64decode(raw + pad).decode("utf-8")
            off_s, sig = dec.split(".", 1)
            off = int(off_s)
            expected = hashlib.sha256((off_s + "|rnd").encode("utf-8")).hexdigest()[:12]
            if sig != expected or off < 0:
                raise ValueError("bad cursor")
            start = off
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            _log("error", meta={"error": e})
            return e

    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(rows)
    if has_more:
        off_s = str(start + limit)
        sig = hashlib.sha256((off_s + "|rnd").encode("utf-8")).hexdigest()[:12]
        next_cursor = base64.urlsafe_b64encode((off_s + "." + sig).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "items": page,
        "total": len(rows),
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order
    }
    _log("ok", meta={"returned": len(page), "total": len(rows)})
    return resp

