            _log("error", meta={"error": e})
            return e

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "Not authorized for this account")
        _log("error", meta={"error": e})
        return e

    cols = _load("collections.json")
    if parent_id is not None:
        p = next((c for c in cols if c.get("id") == parent_id and c.get("account_id") == account_id), None)
        if not p or p.get("status") != "active":
            e = _err("UNAUTHORIZED", "Cannot create under the specified parent collection")
            _log("error", meta={"error": e})
            return e

    # uniqueness: unique(account_id, parent_id, title) where status='active'
    for c in cols:
        if c.get("account_id") == account_id and c.get("parent_id") == parent_id and c.get("status") == "active":
            if (c.get("title") or "") == title:
                e = _err("CONFLICT", "A collection with this title already exists under the same parent", field="title")
                _log("error", meta={"error": e})
                return e

    # choose next sort_order within parent among active
    max_so = -1
    for c in cols:
        if c.get("account_id") == account_id and c.get("parent_id") == parent_id and c.get("status") == "active":
            try:
                so = int(c.get("sort_order", 0))
            except Exception:
                so = 0
            if so > max_so:
                max_so = so
    sort_order = max_so + 1

    new_id = "rnd_col_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=")[:26]
    now = _now()
    rec = {
        "id": new_id,
        "account_id": account_id,
        "parent_id": parent_id,
        "title": title.strip(),
        "view": view,
        "is_public": bool(public) if public is not None else False,
        "expanded": False,
        "sort_order": sort_order,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }

    cols.append(rec)
    _save("collections.json", cols)
    _log("ok", meta={"created_id": new_id})
    return {"item": rec}

def update_collection(collection_id, title=None, view=None, public=None, parent_id=None, expanded=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "update_collection"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # usage log + simple rate limit: 120 req/min per account (best-effort if no usage store)
    usage_file_candidates = ["request_logs.json", "usage.json", "audit.json", "requests.json"]
    usage_file = None
    for fn in usage_file_candidates:
        if os.path.exists(os.path.join(_DB, fn)):
            usage_file = fn
            break
    if usage_file is None:
        usage_file = "request_logs.json"
        # ensure file exists
        if not os.path.exists(os.path.join(_DB, usage_file)):
            _save(usage_file, [])

    def _log(account_id, credential_id, status, error_code=None):
        logs = _load(usage_file)
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "timestamp": now,
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
        }
        logs.append(row)
        _save(usage_file, logs)

    def _rate_limited(account_id):
        logs = _load(usage_file)
        if not account_id:
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-5000:]):
            if r.get("account_id") != account_id:
                continue
            ts = r.get("timestamp")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            c += 1
            if c >= 120:
                return True
        return False

    # Validate collection_id
    if not isinstance(collection_id, str) or not re.match(r"^rnd_col_[0-9A-Z]{26}$", collection_id or ""):
        _log(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_id is missing or invalid", field="collection_id")

    if title is not None and (not isinstance(title, str) or len(title.strip()) < 1):
        _log(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
    if view is not None and (not isinstance(view, str) or view not in ("list", "grid", "masonry", "simple")):
        _log(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "view is invalid", field="view", allowed=["list", "grid", "masonry", "simple"])
    if public is not None and not isinstance(public, bool):
        _log(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "public must be boolean", field="public")
    if expanded is not None and not isinstance(expanded, bool):
        _log(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "expanded must be boolean", field="expanded")
    if parent_id is not None:
        if not isinstance(parent_id, str) or not re.match(r"^rnd_col_[0-9A-Z]{26}$", parent_id):
            _log(None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_id is malformed", field="parent_id")

    accounts = _load("accounts.json")
    collections = _load("collections.json")

    # Ambient auth resolution: find an account that owns this active collection
    target = None
    for c in collections:
        if c.get("id") == collection_id and c.get("status") == "active":
            target = c
            break
    if not target:
        _log(None, None, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Collection not found")

    account_id = target.get("account_id")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        _log(account_id, None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active account context available for this operation")

    if _rate_limited(account_id):
        _log(account_id, None, 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Parent validation and cycle prevention
    if parent_id is not None:
        if parent_id == collection_id:
            _log(account_id, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_id cannot equal collection_id", field="parent_id")

        new_parent = next((c for c in collections if c.get("id") == parent_id), None)
        if not new_parent or new_parent.get("status") != "active":
            _log(account_id, None, 404, "NOT_FOUND")
            return _err("NOT_FOUND", "Parent collection not found or not active")
        if new_parent.get("account_id") != account_id:
            _log(account_id, None, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Cannot assign parent from another account")

        # cycle check: walk up from new_parent to root
        by_id = {c.get("id"): c for c in collections if isinstance(c, dict)}
        cur = new_parent
        steps = 0
        while cur and cur.get("parent_id") is not None and steps < 1000:
            pid = cur.get("parent_id")
            if pid == collection_id:
                _log(account_id, None, 409, "CONFLICT")
                return _err("CONFLICT", "parent_id would create a cycle")
            cur = by_id.get(pid)
            steps += 1

    # Enforce unique(account_id, parent_id, title) where status='active' if title or parent_id changes
    new_title = target.get("title") if title is None else title.strip()
    new_parent_id = target.get("parent_id") if parent_id is None else parent_id
    for c in collections:
        if c.get("id") == collection_id:
            continue
        if c.get("account_id") == account_id and c.get("status") == "active":
            if c.get("parent_id") == new_parent_id and c.get("title") == new_title:
                _log(account_id, None, 409, "CONFLICT")
                return _err("CONFLICT", "A collection with the same title already exists under this parent")

    # Apply updates only for provided fields
    changed = False
    if title is not None and target.get("title") != new_title:
        target["title"] = new_title
        changed = True
    if view is not None and target.get("view") != view:
        target["view"] = view
        changed = True
    if public is not None and target.get("is_public") != public:
        target["is_public"] = public
        changed = True
    if expanded is not None and target.get("expanded") != expanded:
        target["expanded"] = expanded
        changed = True
    if parent_id is not None and target.get("parent_id") != parent_id:
        target["parent_id"] = parent_id
        changed = True

    if changed:
        target["updated_at"] = now
        _save("collections.json", collections)

    _log(account_id, None, 200, None)
    return {"collection": target, "changed": changed}

