    col = next((c for c in collections if c.get("id") == collection_id), None)
    if not col or col.get("status") != "active":
        _log(None, None, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Collection not found")

    account_id = col.get("account_id")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        _log(account_id, None, 401, "UNAUTHORIZED")
