    if _rate_limited(account_id):
        _log(account_id, None, 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # lifecycle transition active -> deleted only
    if col.get("status") != "active":
        _log(account_id, None, 409, "CONFLICT")
        return _err("CONFLICT", "Collection cannot be deleted in its current state")

    # Soft delete
    col["status"] = "deleted"
    col["deleted_at"] = now
    col["updated_at"] = now

    # Move raindrops in this collection (active only) to trash and unsort them
    moved = 0
    for r in raindrops:
        if r.get("account_id") != account_id:
            continue
        if r.get("collection_id") == collection_id and r.get("status") == "active":
            r["status"] = "trashed"
            r["trashed_at"] = now
            r["collection_id"] = None
            r["updated_at"] = now
            moved += 1

    _save("collections.json", collections)
    if moved:
        _save("raindrops.json", raindrops)

    _log(account_id, None, 200, None)
    return {"collection": col, "raindrops_moved_to_trash": moved}

