def get_raindrop(raindrop_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_raindrop"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_file_candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "request_log.json"]
    usage_file = next((fn for fn in usage_file_candidates if os.path.exists(os.path.join(_DB, fn))), "request_logs.json")
    if not os.path.exists(os.path.join(_DB, usage_file)):
        _save(usage_file, [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _log(account_id, status, error_code=None, detail=None):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "timestamp": now_iso,
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _check_limits(account_id):
        if not account_id:
            return None
        logs = _load(usage_file)
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        min_cutoff = now_dt - datetime.timedelta(seconds=60)
        day_cutoff = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= min_cutoff:
                per_min += 1
            if ts >= day_cutoff:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate inputs (relax: accept correct ids; do not reject due to auth context bugs)
    if not isinstance(raindrop_id, str) or not raindrop_id:
        _log(None, "error", "VALIDATION_ERROR", "raindrop_id missing")
        return _err("VALIDATION_ERROR", "raindrop_id is missing or invalid", field="raindrop_id")
    if not re.match(r"^rnd_rdp_[0-9A-Z]{26}$", raindrop_id):
        _log(None, "error", "VALIDATION_ERROR", "raindrop_id pattern")
        return _err("VALIDATION_ERROR", "raindrop_id is missing or invalid", field="raindrop_id")

    raindrops = _load("raindrops.json")
    if not isinstance(raindrops, list):
        raindrops = []

    r = next((x for x in raindrops if x.get("id") == raindrop_id), None)
    if not r or r.get("status") == "deleted":
        _log(None, "not_found", "NOT_FOUND", "raindrop not found")
        return _err("NOT_FOUND", "Raindrop not found")

    # Ambient auth: choose an account context that can serve the request.
    # If the raindrop is owned by an existing active account, use that; otherwise search for any active account.
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == r.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        acct = next((a for a in accounts if a.get("status") == "active"), None)
    if not acct:
        _log(None, "error", "UNAUTHORIZED", "no active account context")
        return _err("UNAUTHORIZED", "Unauthorized")

    account_id = acct.get("id")

    limit_err = _check_limits(account_id)
    if limit_err:
        _log(account_id, "error", limit_err["error"]["code"], limit_err["error"]["message"])
        return limit_err

    # Access control: you can only read owned raindrops, and only active/trashed are returned
    if r.get("account_id") != account_id:
        _log(account_id, "error", "NOT_FOUND", "cross-account")
        return _err("NOT_FOUND", "Raindrop not found")
    if r.get("status") not in ("active", "trashed"):
        _log(account_id, "not_found", "NOT_FOUND", "not accessible status")
        return _err("NOT_FOUND", "Raindrop not found")

    # If it references a collection, ensure it's active & owned; otherwise treat as not accessible (NOT_FOUND)
    col_id = r.get("collection_id")
    if col_id is not None:
        collections = _load("collections.json")
        if not isinstance(collections, list):
            collections = []
        col = next((c for c in collections if c.get("id") == col_id), None)
        if not col or col.get("account_id") != account_id or col.get("status") != "active":
            _log(account_id, "error", "NOT_FOUND", "collection not accessible")
            return _err("NOT_FOUND", "Raindrop not found")

    # Update last_accessed_at (observable side-effect)
    now = now_iso
    changed = False
    for i, x in enumerate(raindrops):
        if x.get("id") == raindrop_id:
            if x.get("last_accessed_at") != now:
                raindrops[i] = dict(x)
                raindrops[i]["last_accessed_at"] = now
                raindrops[i]["updated_at"] = x.get("updated_at") or now
                changed = True
            r = raindrops[i]
            break
    if changed:
        _save("raindrops.json", raindrops)

    _log(account_id, "ok")
    return {"item": r}

def get_raindrops(collection_id, search=None, sort=None, page=None, perpage=None, nested=None, **_extra):
    import json, os, datetime, time, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_raindrops"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Logging file
    usage_file_candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "request_log.json"]
    usage_file = None
    for fn in usage_file_candidates:
        if os.path.exists(os.path.join(_DB, fn)):
            usage_file = fn
            break
    if usage_file is None:
        usage_file = "request_logs.json"
        if not os.path.exists(os.path.join(_DB, usage_file)):
            _save(usage_file, [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _log(account_id, status, error_code=None, detail=None):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "timestamp": now,
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _check_limits(account_id):
        logs = _load(usage_file)
        if not isinstance(logs, list) or not account_id:
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        min_cutoff = now_dt - datetime.timedelta(seconds=60)
        day_cutoff = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reversed(logs[-10000:]):
            if r.get("account_id") != account_id:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= day_cutoff:
                per_day += 1
                if dt >= min_cutoff:
                    per_min += 1
            if per_min >= 120:
                return _err("RATE_LIMIT", "Rate limit exceeded")
            if per_day >= 10000:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    # ---- Validate inputs (collection_id is integer per tool schema) ----
    if not isinstance(collection_id, int):
        _log(None, "error", "VALIDATION_ERROR", "collection_id must be integer")
        return _err("VALIDATION_ERROR", "collection_id must be an integer", field="collection_id")

    if page is None:
        page = 0
    if perpage is None:
        perpage = 25
    if nested is None:
        nested = False
    if sort is None:
        sort = "-created"

    if not isinstance(page, int) or page < 0:
        _log(None, "error", "VALIDATION_ERROR", "invalid page")
        return _err("VALIDATION_ERROR", "page must be an integer >= 0", field="page")
    if not isinstance(perpage, int) or perpage < 1 or perpage > 50:
        _log(None, "error", "VALIDATION_ERROR", "invalid perpage")
        return _err("VALIDATION_ERROR", "perpage must be an integer in [1,50]", field="perpage")
    if not isinstance(nested, bool):
        _log(None, "error", "VALIDATION_ERROR", "invalid nested")
        return _err("VALIDATION_ERROR", "nested must be a boolean", field="nested")

    allowed_sorts = {"-created", "created", "score", "-sort", "title", "-title", "domain", "-domain"}
    if sort not in allowed_sorts:
        _log(None, "error", "VALIDATION_ERROR", "invalid sort")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")
    if sort == "score" and (search is None or (isinstance(search, str) and search.strip() == "")):
        _log(None, "error", "VALIDATION_ERROR", "score without search")
        return _err("VALIDATION_ERROR", "sort='score' is only valid when search is provided", field="sort")
    if search is not None and not isinstance(search, str):
        _log(None, "error", "VALIDATION_ERROR", "search type")
        return _err("VALIDATION_ERROR", "search must be a string", field="search")

    search_q = (search or "").strip()
    use_search = bool(search_q)

    # ---- Ambient auth: pick an account that can serve this request ----
    # Since no auth parameter exists, choose an active/suspended account with any data;
    # to avoid refusing valid calls, prefer the account owning the relevant collection if possible.
    raindrops = _load("raindrops.json")
    if not isinstance(raindrops, list):
        raindrops = []
    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    def _acct_ok(aid):
        return any(isinstance(a, dict) and a.get("id") == aid and a.get("status") in ("active", "suspended") for a in accounts)

    # Determine candidate account_ids based on scope
    candidate_account_ids = []
    if collection_id in (0, -1, -99):
        # pick any account that has raindrops matching scope; else any active account
        for r in raindrops:
            if not isinstance(r, dict):
                continue
            st = r.get("status")
            if collection_id == -99:
                ok = (st == "trashed")
            else:
                ok = (st == "active") and ((collection_id == 0) or (collection_id == -1 and r.get("collection_id") is None))
            if ok:
                aid = r.get("account_id")
                if isinstance(aid, str) and _acct_ok(aid) and aid not in candidate_account_ids:
                    candidate_account_ids.append(aid)
        if not candidate_account_ids:
            for a in accounts:
                if isinstance(a, dict) and a.get("status") in ("active", "suspended") and isinstance(a.get("id"), str):
                    candidate_account_ids.append(a["id"])
                    break
    else:
        # For integer other than special, treat as "no results" scope (no validation error per audit);
        # choose any active account to keep logging/quota consistent.
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("active", "suspended") and isinstance(a.get("id"), str):
                candidate_account_ids.append(a["id"])
                break

    if not candidate_account_ids:
        _log(None, "error", "UNAUTHORIZED", "no account context")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    account_id = candidate_account_ids[0]
    lim_err = _check_limits(account_id)
    if lim_err:
        _log(account_id, "error", lim_err["error"]["code"])
        return lim_err

    # ---- Scope selection ----
    # tool schema only accepts integer; business rules define meaning for 0/-1/-99, otherwise treat as empty scope.
    def _in_scope(r):
        if not isinstance(r, dict):
            return False
        if r.get("account_id") != account_id:
            return False
        st = r.get("status")
        if collection_id == 0:
            return st == "active"
        if collection_id == -1:
            return st == "active" and r.get("collection_id") is None
        if collection_id == -99:
            return st == "trashed"
        # unknown int => no matches
        return False

    scoped = [r for r in raindrops if _in_scope(r)]

    # ---- Search over title/excerpt/link/domain/tags ----
    if use_search:
        raindrop_tags = _load("raindrop_tags.json")
        if not isinstance(raindrop_tags, list):
            raindrop_tags = []
        tags_tbl = _load("tags.json")
        if not isinstance(tags_tbl, list):
            tags_tbl = []
        tag_name_by_id = {}
        for t in tags_tbl:
            if isinstance(t, dict) and t.get("account_id") == account_id and isinstance(t.get("id"), str):
                nm = t.get("name")
                if isinstance(nm, str):
                    tag_name_by_id[t["id"]] = nm

        tag_names_by_rid = {}
        for rt in raindrop_tags:
            if not isinstance(rt, dict):
                continue
            if rt.get("account_id") != account_id:
                continue
            rid = rt.get("raindrop_id")
            tid = rt.get("tag_id")
            if rid in (None, "") or tid in (None, ""):
                continue
            nm = tag_name_by_id.get(tid)
            if nm:
                tag_names_by_rid.setdefault(rid, []).append(nm)

        q = search_q.lower()

        def _text(r):
            parts = []
            for k in ("title", "excerpt", "link", "domain"):
                v = r.get(k)
                if isinstance(v, str) and v:
                    parts.append(v)
            for nm in tag_names_by_rid.get(r.get("id"), []) or []:
                parts.append(nm)
            return " ".join(parts)

        scored = []
        for r in scoped:
            txt = _text(r).lower()
            if q in txt:
                # simple relevance: occurrences count + prefix bonus
                occ = txt.count(q)
                bonus = 2 if (isinstance(r.get("title"), str) and r.get("title").lower().startswith(q)) else 0
                scored.append((occ + bonus, r))
        if sort == "score":
            scored.sort(key=lambda x: (-x[0], x[1].get("created_at") or ""), reverse=False)
            scoped = [r for _, r in scored]
        else:
            scoped = [r for _, r in scored]

    # ---- Sorting ----
    def _dt_key(s):
        if not isinstance(s, str):
            return ""
        return s

    if sort == "-created":
        scoped.sort(key=lambda r: _dt_key(r.get("created_at")), reverse=True)
    elif sort == "created":
        scoped.sort(key=lambda r: _dt_key(r.get("created_at")), reverse=False)
    elif sort == "title":
        scoped.sort(key=lambda r: (str(r.get("title") or "").lower(), _dt_key(r.get("created_at"))))
    elif sort == "-title":
        scoped.sort(key=lambda r: (str(r.get("title") or "").lower(), _dt_key(r.get("created_at"))), reverse=True)
    elif sort == "domain":
        scoped.sort(key=lambda r: (str(r.get("domain") or "").lower(), str(r.get("title") or "").lower()))
    elif sort == "-domain":
        scoped.sort(key=lambda r: (str(r.get("domain") or "").lower(), str(r.get("title") or "").lower()), reverse=True)
    elif sort == "-sort":
        scoped.sort(key=lambda r: (int(r.get("order") or 0), _dt_key(r.get("created_at"))), reverse=False)

    total = len(scoped)
    start = page * perpage
    end = start + perpage
    items = scoped[start:end]
    has_more = end < total

    _log(account_id, "ok", None, None)
    return {
        "items": items,
        "meta": {
            "total": total,
            "page": page,
            "perpage": perpage,
            "has_more": has_more
        }
    }

def get_tags(collection_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, detail=None, account_id=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "account_id": account_id,
                "status": status,
                "detail": detail,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if collection_id is not None:
        if not isinstance(collection_id, str):
            _log("get_tags", "error", "collection_id type")
            return _err("VALIDATION_ERROR", "collection_id must be a string")
        if not re.match(r"^rnd_col_[0-9A-Z]{26}$", collection_id):
            _log("get_tags", "error", "collection_id pattern")
            return _err("VALIDATION_ERROR", "collection_id has invalid format")

    accounts = _load("accounts.json")
    collections = _load("collections.json")
    raindrops = _load("raindrops.json")
    tags = _load("tags.json")
    rtags = _load("raindrop_tags.json")

    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
    if not active_accounts:
        _log("get_tags", "error", "no active account")
        return _err("UNAUTHORIZED", "No authenticated account context available")
    account_id = active_accounts[0]["id"]

    col_by_id = {c.get("id"): c for c in collections if isinstance(c, dict) and isinstance(c.get("id"), str)}
    if collection_id is not None:
        c = col_by_id.get(collection_id)
        if not c or c.get("account_id") != account_id or c.get("status") != "active":
            _log("get_tags", "error", "collection not found", account_id=account_id)
            return _err("NOT_FOUND", "Collection not found")

    # Determine raindrop scope: for this endpoint, collection_id is string id; if omitted => all active raindrops.
    scoped_raindrop_ids = set()
    if collection_id is None:
        for r in raindrops:
            if isinstance(r, dict) and r.get("account_id") == account_id and r.get("status") == "active":
                scoped_raindrop_ids.add(r.get("id"))
    else:
        for r in raindrops:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            if r.get("status") != "active":
                continue
            if r.get("collection_id") == collection_id:
                scoped_raindrop_ids.add(r.get("id"))

    # Count tags attached via raindrop_tags
    tag_counts = {}
    for rt in rtags:
        if not isinstance(rt, dict):
            continue
        if rt.get("account_id") != account_id:
            continue
        rid = rt.get("raindrop_id")
        tid = rt.get("tag_id")
        if rid in scoped_raindrop_ids and tid:
            tag_counts[tid] = tag_counts.get(tid, 0) + 1

    # Build response rows from real tag rows
    tag_by_id = {t.get("id"): t for t in tags if isinstance(t, dict) and t.get("account_id") == account_id}
    rows = []
    for tid, cnt in tag_counts.items():
        t = tag_by_id.get(tid)
        if not t:
            continue
        rows.append({
            "id": t.get("id"),
            "name": t.get("name"),
            "count": cnt,
            "created_at": t.get("created_at"),
            "updated_at": t.get("updated_at"),
        })

    rows.sort(key=lambda x: (-(x.get("count") or 0), (x.get("name") or "").lower(), x.get("id") or ""))

    _log("get_tags", "ok", account_id=account_id)
    return {
        "items": rows,
        "meta": {
            "total": len(rows),
            "collection_id": collection_id,
        }
    }

def update_raindrop(raindrop_id, title=None, excerpt=None, link=None, important=None, tags=None, collection_id=None, cover=None, type=None, order=None, **_extra):
    import json, os, datetime, time, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_raindrop"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_file_candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "request_log.json"]
    usage_file = next((fn for fn in usage_file_candidates if os.path.exists(os.path.join(_DB, fn))), "request_logs.json")
    if not os.path.exists(os.path.join(_DB, usage_file)):
        _save(usage_file, [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _log(account_id, status, error_code=None, detail=None):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "timestamp": now_iso,
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _check_limits(account_id):
        if not account_id:
            return None
        logs = _load(usage_file)
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        min_cutoff = now_dt - datetime.timedelta(seconds=60)
        day_cutoff = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= min_cutoff:
                per_min += 1
            if ts >= day_cutoff:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate raindrop_id
    if not isinstance(raindrop_id, str) or not raindrop_id or not re.match(r"^rnd_rdp_[0-9A-Z]{26}$", raindrop_id):
        _log(None, "error", "VALIDATION_ERROR", "raindrop_id invalid")
        return _err("VALIDATION_ERROR", "raindrop_id is missing or invalid", field="raindrop_id")

    # Validate optional fields
    if title is not None and not isinstance(title, str):
        _log(None, "error", "VALIDATION_ERROR", "title type")
        return _err("VALIDATION_ERROR", "title must be a string", field="title")
    if excerpt is not None and not isinstance(excerpt, str):
        _log(None, "error", "VALIDATION_ERROR", "excerpt type")
        return _err("VALIDATION_ERROR", "excerpt must be a string", field="excerpt")
    if link is not None:
        if not isinstance(link, str) or not link:
            _log(None, "error", "VALIDATION_ERROR", "link type")
            return _err("VALIDATION_ERROR", "link must be a non-empty string", field="link")
        try:
            u = urllib.parse.urlparse(link)
            if not u.scheme or not u.netloc:
                _log(None, "error", "VALIDATION_ERROR", "link format")
                return _err("VALIDATION_ERROR", "link must be a valid URL", field="link")
        except Exception:
            _log(None, "error", "VALIDATION_ERROR", "link parse")
            return _err("VALIDATION_ERROR", "link must be a valid URL", field="link")
    if important is not None and not isinstance(important, bool):
        _log(None, "error", "VALIDATION_ERROR", "important type")
        return _err("VALIDATION_ERROR", "important must be boolean", field="important")
    if cover is not None and not isinstance(cover, str):
        _log(None, "error", "VALIDATION_ERROR", "cover type")
        return _err("VALIDATION_ERROR", "cover must be a string", field="cover")
    if type is not None:
        allowed = {"link", "article", "video", "image", "document", "audio", "other"}
        if not isinstance(type, str) or type not in allowed:
            _log(None, "error", "VALIDATION_ERROR", "type enum")
            return _err("VALIDATION_ERROR", "type must be one of: link, article, video, image, document, audio, other", field="type")
    if order is not None:
        if not isinstance(order, int):
            _log(None, "error", "VALIDATION_ERROR", "order type")
            return _err("VALIDATION_ERROR", "order must be an integer", field="order")
        if order < 0:
            _log(None, "error", "VALIDATION_ERROR", "order range")
            return _err("VALIDATION_ERROR", "order must be >= 0", field="order")
    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^rnd_col_[0-9A-Z]{26}$", collection_id):
            _log(None, "error", "VALIDATION_ERROR", "collection_id pattern")
            return _err("VALIDATION_ERROR", "collection_id is invalid", field="collection_id")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log(None, "error", "VALIDATION_ERROR", "tags type")
            return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")

    raindrops = _load("raindrops.json")
    if not isinstance(raindrops, list):
        raindrops = []
    idx = next((i for i, x in enumerate(raindrops) if x.get("id") == raindrop_id), None)
    if idx is None:
        _log(None, "not_found", "NOT_FOUND", "raindrop not found")
        return _err("NOT_FOUND", "Raindrop not found")

    existing = raindrops[idx]
    if existing.get("status") not in ("active", "trashed"):
        _log(existing.get("account_id"), "not_found", "NOT_FOUND", "not updatable status")
        return _err("NOT_FOUND", "Raindrop not found")

    # Ambient auth: require raindrop's owning account exists and is active
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == existing.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        acct = next((a for a in accounts if a.get("status") == "active"), None)
    if not acct:
        _log(None, "error", "UNAUTHORIZED", "no active account")
        return _err("UNAUTHORIZED", "Unauthorized")
    account_id = acct.get("id")
    if existing.get("account_id") != account_id:
        _log(account_id, "not_found", "NOT_FOUND", "cross-account")
        return _err("NOT_FOUND", "Raindrop not found")

    limit_err = _check_limits(account_id)
    if limit_err:
        _log(account_id, "error", limit_err["error"]["code"], limit_err["error"]["message"])
        return limit_err

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []

    # Validate destination collection if moving
    dest_collection_id = collection_id if collection_id is not None else None
    if dest_collection_id is not None:
        col = next((c for c in collections if c.get("id") == dest_collection_id), None)
        if not col or col.get("account_id") != account_id or col.get("status") != "active":
            _log(account_id, "error", "NOT_FOUND", "destination collection")
            return _err("NOT_FOUND", "Destination collection not found")

    # Enforce unique(account_id, link, status) where status != 'deleted' if link changes
    new_status = existing.get("status")
    new_link = existing.get("link")
    if link is not None:
        new_link = link
        for x in raindrops:
            if x.get("id") == raindrop_id:
                continue
            if x.get("account_id") == account_id and x.get("status") != "deleted" and x.get("status") == new_status and x.get("link") == new_link:
                _log(account_id, "error", "CONFLICT", "duplicate link/status")
                return _err("CONFLICT", "A raindrop with the same link already exists in this state")

    updated = dict(existing)
    changed = False

    def _set(field, value):
        nonlocal changed, updated
        if updated.get(field) != value:
            updated[field] = value
            changed = True

    if title is not None:
        _set("title", title)
    if excerpt is not None:
        _set("excerpt", excerpt)
    if link is not None:
        _set("link", link)
        try:
            d = urllib.parse.urlparse(link).netloc.lower()
        except Exception:
            d = None
        _set("domain", d if d else updated.get("domain"))
    if important is not None:
        _set("important", important)
    if cover is not None:
        _set("cover_url", cover)
    if type is not None:
        _set("type", type)
    if order is not None:
        _set("order", order)
    if collection_id is not None:
        _set("collection_id", dest_collection_id)

    # Tags replacement (if provided)
    if tags is not None:
        tags_rows = _load("tags.json")
        if not isinstance(tags_rows, list):
            tags_rows = []
        rdt_rows = _load("raindrop_tags.json")
        if not isinstance(rdt_rows, list):
            rdt_rows = []

        def _norm(s):
            return " ".join(s.strip().split()).lower()

        desired_norms = []
        desired_display = {}
        for t in tags:
            n = _norm(t)
            if not (1 <= len(n) <= 64):
                _log(account_id, "error", "VALIDATION_ERROR", "tag length")
                return _err("VALIDATION_ERROR", "tag names must be 1..64 characters after normalization", field="tags")
            if n not in desired_display:
                desired_norms.append(n)
                desired_display[n] = t.strip()

        now = now_iso
        # upsert tags by (account_id, name_normalized)
        norm_to_tag_id = {}
        for n in desired_norms:
            existing_tag = next((tr for tr in tags_rows if tr.get("account_id") == account_id and tr.get("name_normalized") == n), None)
            if existing_tag:
                norm_to_tag_id[n] = existing_tag.get("id")
                # touch updated_at, and preserve case if changed
                if existing_tag.get("name") != desired_display[n]:
                    existing_tag["name"] = desired_display[n]
                    existing_tag["updated_at"] = now
                continue
            # create new tag
            new_id = "rnd_tag_" + datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f").upper().ljust(26, "0")[:26]
            tags_rows.append({
                "id": new_id,
                "account_id": account_id,
                "name": desired_display[n],
                "name_normalized": n,
                "created_at": now,
                "updated_at": now
            })
            norm_to_tag_id[n] = new_id

        # set raindrop_tags exactly to desired set
        existing_links = [rt for rt in rdt_rows if rt.get("raindrop_id") == raindrop_id]
        existing_tag_ids = {rt.get("tag_id") for rt in existing_links}
        desired_tag_ids = {norm_to_tag_id[n] for n in desired_norms}

        # delete removed
        if existing_links:
            new_rdt = [rt for rt in rdt_rows if not (rt.get("raindrop_id") == raindrop_id and rt.get("tag_id") not in desired_tag_ids)]
        else:
            new_rdt = list(rdt_rows)

        # add missing
        def _new_rdt_id():
            return "rnd_rdt_" + datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f").upper().ljust(26, "0")[:26]

        for tid in desired_tag_ids:
            if tid in existing_tag_ids:
                continue
            new_rdt.append({
                "id": _new_rdt_id(),
                "account_id": account_id,
                "raindrop_id": raindrop_id,
                "tag_id": tid,
                "created_at": now,
                "updated_at": now
            })

        # persist tag/assignment updates even if raindrop fields otherwise unchanged
        _save("tags.json", tags_rows)
        _save("raindrop_tags.json", new_rdt)

    if not changed and tags is None:
        _log(account_id, "error", "NOT_FOUND", "no fields changed")
        return _err("NOT_FOUND", "No changes applied")

    if changed:
        updated["updated_at"] = now_iso
        raindrops[idx] = updated
        _save("raindrops.json", raindrops)

    _log(account_id, "ok")
    return {"item": raindrops[idx]}

def update_many_raindrops(collection_id, ids=None, important=None, tags=None, cover=None, target_collection_id=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_many_raindrops"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_file_candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "request_log.json"]
    usage_file = next((fn for fn in usage_file_candidates if os.path.exists(os.path.join(_DB, fn))), "request_logs.json")
    if not os.path.exists(os.path.join(_DB, usage_file)):
        _save(usage_file, [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _log(account_id, status, error_code=None, detail=None):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "timestamp": now_iso,
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _check_limits(account_id):
        if not account_id:
            return None
        logs = _load(usage_file)
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        min_cutoff = now_dt - datetime.timedelta(seconds=60)
        day_cutoff = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= min_cutoff:
                per_min += 1
            if ts >= day_cutoff:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate collection_id
    if not isinstance(collection_id, str) or not re.match(r"^rnd_col_[0-9A-Z]{26}$", collection_id):
        _log(None, "error", "VALIDATION_ERROR", "collection_id invalid")
        return _err("VALIDATION_ERROR", "collection_id is missing or invalid", field="collection_id")

    if ids is not None:
        if not isinstance(ids, list) or any((not isinstance(i, str) or not re.match(r"^rnd_rdp_[0-9A-Z]{26}$", i)) for i in ids):
            _log(None, "error", "VALIDATION_ERROR", "ids invalid")
            return _err("VALIDATION_ERROR", "ids must be an array of raindrop ids", field="ids")

    if important is not None and not isinstance(important, bool):
        _log(None, "error", "VALIDATION_ERROR", "important type")
        return _err("VALIDATION_ERROR", "important must be boolean", field="important")

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log(None, "error", "VALIDATION_ERROR", "tags type")
            return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")

    if cover is not None and not isinstance(cover, str):
        _log(None, "error", "VALIDATION_ERROR", "cover type")
        return _err("VALIDATION_ERROR", "cover must be a string", field="cover")

    if target_collection_id is not None:
        if not isinstance(target_collection_id, str) or not re.match(r"^rnd_col_[0-9A-Z]{26}$", target_collection_id):
            _log(None, "error", "VALIDATION_ERROR", "target_collection_id invalid")
            return _err("VALIDATION_ERROR", "target_collection_id is invalid", field="target_collection_id")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []

    src_col = next((c for c in collections if c.get("id") == collection_id and c.get("status") == "active"), None)
    if not src_col:
        _log(None, "not_found", "NOT_FOUND", "source collection")
        return _err("NOT_FOUND", "Collection not found")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == src_col.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        acct = next((a for a in accounts if a.get("status") == "active"), None)
    if not acct:
        _log(None, "error", "UNAUTHORIZED", "no active account")
        return _err("UNAUTHORIZED", "Unauthorized")

    account_id = acct.get("id")
    if src_col.get("account_id") != account_id:
        _log(account_id, "not_found", "NOT_FOUND", "cross-account collection")
        return _err("NOT_FOUND", "Collection not found")

    limit_err = _check_limits(account_id)
    if limit_err:
        _log(account_id, "error", limit_err["error"]["code"], limit_err["error"]["message"])
        return limit_err

    dest_id = None
    if target_collection_id is not None:
        dest_id = target_collection_id
        dest_col = next((c for c in collections if c.get("id") == dest_id), None)
        if not dest_col or dest_col.get("account_id") != account_id or dest_col.get("status") != "active":
            _log(account_id, "error", "NOT_FOUND", "destination collection")
            return _err("NOT_FOUND", "Destination collection not found")

    # Determine candidates: scope is "within a collection" (active raindrops in that collection)
    raindrops = _load("raindrops.json")
    if not isinstance(raindrops, list):
        raindrops = []

    candidates = [r for r in raindrops if r.get("account_id") == account_id and r.get("status") == "active" and r.get("collection_id") == collection_id]
    if ids is not None:
        wanted = set(ids)
        candidates = [r for r in candidates if r.get("id") in wanted]

    # Must have effect
    if not candidates:
        _log(account_id, "not_found", "NOT_FOUND", "no matching raindrops")
        return _err("NOT_FOUND", "No raindrops matched the requested scope/ids")

    if important is None and tags is None and cover is None and target_collection_id is None:
        _log(account_id, "error", "VALIDATION_ERROR", "no operations")
        return _err("VALIDATION_ERROR", "At least one of important, tags, cover, target_collection_id must be provided")

    # Prepare tags upserts once (if tags provided)
    tags_rows = None
    rdt_rows = None
    desired_tag_ids = None

    def _norm(s):
        return " ".join(s.strip().split()).lower()

    if tags is not None:
        tags_rows = _load("tags.json")
        if not isinstance(tags_rows, list):
            tags_rows = []
        rdt_rows = _load("raindrop_tags.json")
        if not isinstance(rdt_rows, list):
            rdt_rows = []

        now = now_iso
        desired_tag_ids = set()
        desired_norms = []
        desired_display = {}
        for t in tags:
            n = _norm(t)
            if not (1 <= len(n) <= 64):
                _log(account_id, "error", "VALIDATION_ERROR", "tag length")
                return _err("VALIDATION_ERROR", "tag names must be 1..64 characters after normalization", field="tags")
            if n not in desired_display:
                desired_display[n] = t.strip()
                desired_norms.append(n)

        for n in desired_norms:
            existing_tag = next((tr for tr in tags_rows if tr.get("account_id") == account_id and tr.get("name_normalized") == n), None)
            if existing_tag:
                desired_tag_ids.add(existing_tag.get("id"))
                if existing_tag.get("name") != desired_display[n]:
                    existing_tag["name"] = desired_display[n]
                    existing_tag["updated_at"] = now
                continue
            new_id = "rnd_tag_" + datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f").upper().ljust(26, "0")[:26]
            tags_rows.append({
                "id": new_id,
                "account_id": account_id,
                "name": desired_display[n],
                "name_normalized": n,
                "created_at": now,
                "updated_at": now
            })
            desired_tag_ids.add(new_id)

    # Apply updates
    now = now_iso
    updated_ids = []
    updated_count = 0

    def _new_rdt_id():
        return "rnd_rdt_" + datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f").upper().ljust(26, "0")[:26]

    for i, r in enumerate(raindrops):
        if r.get("id") not in {c.get("id") for c in candidates}:
            continue

        changed = False
        rr = dict(r)

        if important is not None and rr.get("important") != important:
            rr["important"] = important
            changed = True

        if cover is not None:
            if cover == "<screenshot>":
                # store as null (background job semantics)
                if rr.get("cover_url") is not None:
                    rr["cover_url"] = None
                    changed = True
            else:
                if rr.get("cover_url") != cover:
                    rr["cover_url"] = cover
                    changed = True

        if target_collection_id is not None:
            if rr.get("collection_id") != dest_id:
                rr["collection_id"] = dest_id
                changed = True

        if tags is not None:
            # replace tag set (empty list clears all)
            rid = rr.get("id")
            existing_links = [rt for rt in rdt_rows if rt.get("raindrop_id") == rid]
            existing_tag_ids = {rt.get("tag_id") for rt in existing_links}
            # delete removed
            rdt_rows = [rt for rt in rdt_rows if not (rt.get("raindrop_id") == rid and rt.get("tag_id") not in desired_tag_ids)]
            # add missing
            for tid in desired_tag_ids:
                if tid in existing_tag_ids:
                    continue
                rdt_rows.append({
                    "id": _new_rdt_id(),
                    "account_id": account_id,
                    "raindrop_id": rid,
                    "tag_id": tid,
                    "created_at": now,
                    "updated_at": now
                })
            if existing_tag_ids != desired_tag_ids:
                changed = True

        if changed:
            rr["updated_at"] = now
            raindrops[i] = rr
            updated_ids.append(rr.get("id"))
            updated_count += 1

    if updated_count == 0 and tags is None:
        _log(account_id, "not_found", "NOT_FOUND", "no changes")
        return _err("NOT_FOUND", "No changes applied")

    # Persist
    _save("raindrops.json", raindrops)
    if tags is not None:
        _save("tags.json", tags_rows)
        _save("raindrop_tags.json", rdt_rows)

    _log(account_id, "ok")
    return {
        "result": {
            "collection_id": collection_id,
            "updated": updated_count,
            "updated_ids": updated_ids
        }
    }

def create_raindrop(collection_id=None, link=None, title=None, excerpt=None, important=None, cover_url=None, type=None, order=None, tags=None, **_extra):
    import json, os, datetime, re, time, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- load store
    accounts = _load("accounts.json")
    collections = _load("collections.json")
    raindrops = _load("raindrops.json")
    tags_tbl = _load("tags.json")
    rdt_tbl = _load("raindrop_tags.json")
    reqlog = _load("request_log.json")

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "create_raindrop",
            "credential_id": credential_id,
            "account_id": _acct.get("id") if isinstance(_acct, dict) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_log.json", reqlog)

    # ---- rate limit (simple: 120 req/min/account if account resolved; else global 120/min)
    def _rate_limited(account_id=None):
        window_s = 60
        limit = 120
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
        cnt = 0
        for r in reqlog:
            if r.get("timestamp", "") >= cutoff:
                if account_id is None:
                    cnt += 1
                else:
                    if r.get("account_id") == account_id:
                        cnt += 1
        return cnt >= limit

    # ---- resolve ambient authentication to some active account that can serve the request
    # If there is exactly one active account, use it; otherwise, choose any active.
    _acct = None
    active_accounts = [a for a in accounts if a.get("status") == "active" and isinstance(a.get("id"), str)]
    if active_accounts:
        _acct = active_accounts[0]

    if not _acct:
        # no usable account context
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    if _rate_limited(_acct["id"]):
        _log("error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- validate inputs
    if not isinstance(link, str) or not link.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "link is required and must be a non-empty string", field="link")

    if title is not None and (not isinstance(title, str) or not title.strip()):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string when provided", field="title")

    if excerpt is not None and not isinstance(excerpt, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "excerpt must be a string when provided", field="excerpt")

    if important is not None and not isinstance(important, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "important must be a boolean when provided", field="important")

    if cover_url is not None and not isinstance(cover_url, str):
        if cover_url is not None:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cover_url must be a string or null", field="cover_url")

    allowed_types = {"link", "article", "image", "video", "document", "audio"}
    if type is not None:
        if not isinstance(type, str) or type not in allowed_types:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "type is invalid", field="type", allowed=sorted(list(allowed_types)))

    if order is not None:
        if not isinstance(order, int) or order < 0:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order must be an integer >= 0 when provided", field="order")

    if collection_id is not None:
        if not isinstance(collection_id, str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "collection_id must be a string or null", field="collection_id")
        if not re.match(r"^rnd_col_[0-9A-Z]{26}$", collection_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "collection_id is malformed", field="collection_id")

    # URL basic validation
    try:
        u = urllib.parse.urlparse(link.strip())
        if u.scheme not in ("http", "https") or not u.netloc:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "link must be a valid http(s) URL", field="link")
    except Exception:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "link must be a valid URL", field="link")

    # Validate collection existence/ownership/active (if provided)
    if collection_id is not None:
        col = next((c for c in collections if c.get("id") == collection_id), None)
        if not col or col.get("account_id") != _acct["id"] or col.get("status") != "active":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "collection_id must reference an existing active collection owned by the account", field="collection_id")

    # tags validation
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(t, str) or not t.strip()) for t in tags):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of non-empty strings when provided", field="tags")

    # Uniqueness constraint: unique(account_id, link, status) where status != 'deleted'
    for r in raindrops:
        if r.get("account_id") == _acct["id"] and r.get("link") == link.strip() and r.get("status") in ("active", "trashed"):
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "A raindrop with the same link already exists for this account (not deleted)", link=link.strip())

    # derive domain
    domain = None
    try:
        domain = urllib.parse.urlparse(link.strip()).netloc.lower() or None
    except Exception:
        domain = None

    # defaults
    if title is None:
        # Minimal derivation: use hostname or link
        title = domain if domain else link.strip()
    if important is None:
        important = False
    if type is None:
        type = "link"
    if order is None:
        order = 0

    # id generation: prefix + 26 base32-ish chars (0-9A-Z)
    def _new_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        import random
        while True:
            s = "".join(random.choice(alphabet) for _ in range(26))
            _id = f"{prefix}{s}"
            if _id not in existing_ids:
                return _id

    new_id = _new_id("rnd_rdp_", {r.get("id") for r in raindrops if isinstance(r.get("id"), str)})

    raindrop = {
        "id": new_id,
        "account_id": _acct["id"],
        "collection_id": collection_id,
        "title": title.strip(),
        "excerpt": excerpt if excerpt is None else excerpt,
        "link": link.strip(),
        "domain": domain,
        "important": bool(important),
        "cover_url": cover_url,
        "type": type,
        "order": int(order),
        "status": "active",
        "trashed_at": None,
        "created_at": now,
        "updated_at": now,
        "last_accessed_at": None
    }

    # persist raindrop
    raindrops.append(raindrop)
    _save("raindrops.json", raindrops)

    # apply tags if provided
    if tags is not None:
        def _norm(name):
            return " ".join(name.strip().split()).lower()

        wanted_norm = []
        for nm in tags:
            nn = _norm(nm)
            if 1 <= len(nn) <= 64 and nn not in wanted_norm:
                wanted_norm.append(nn)

        # upsert tags
        existing_tag_ids = {t.get("id") for t in tags_tbl if isinstance(t.get("id"), str)}
        def _new_tag_id():
            return _new_id("rnd_tag_", existing_tag_ids)

        norm_to_tag = {(t.get("account_id"), t.get("name_normalized")): t for t in tags_tbl}
        tag_ids = []
        for nn in wanted_norm:
            key = (_acct["id"], nn)
            trow = norm_to_tag.get(key)
            if trow:
                # touch updated_at
                trow["updated_at"] = now
                tag_ids.append(trow["id"])
            else:
                tid = _new_tag_id()
                # preserve original casing by taking first matching input
                original = next((x.strip() for x in tags if _norm(x) == nn), nn)
                trow = {
                    "id": tid,
                    "account_id": _acct["id"],
                    "name": original,
                    "name_normalized": nn,
                    "created_at": now,
                    "updated_at": now
                }
                tags_tbl.append(trow)
                norm_to_tag[key] = trow
                existing_tag_ids.add(tid)
                tag_ids.append(tid)

        # create raindrop_tags assignments (unique(raindrop_id, tag_id))
        existing_pairs = {(x.get("raindrop_id"), x.get("tag_id")) for x in rdt_tbl}
        existing_ids = {x.get("id") for x in rdt_tbl if isinstance(x.get("id"), str)}
        for tid in tag_ids:
            if (new_id, tid) in existing_pairs:
                continue
            rid = _new_id("rnd_rdt_", existing_ids)
            existing_ids.add(rid)
            rdt_tbl.append({
                "id": rid,
                "account_id": _acct["id"],
                "raindrop_id": new_id,
                "tag_id": tid,
                "created_at": now,
                "updated_at": now
            })
            existing_pairs.add((new_id, tid))

        _save("tags.json", tags_tbl)
        _save("raindrop_tags.json", rdt_tbl)

    _log("ok")
    return {"item": raindrop}

def delete_raindrop(raindrop_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_raindrop"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_file_candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "request_log.json"]
    usage_file = next((fn for fn in usage_file_candidates if os.path.exists(os.path.join(_DB, fn))), "request_logs.json")
    if not os.path.exists(os.path.join(_DB, usage_file)):
        _save(usage_file, [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _log(account_id, status, error_code=None, detail=None):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "timestamp": now_iso,
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _check_limits(account_id):
        if not account_id:
            return None
        logs = _load(usage_file)
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        min_cutoff = now_dt - datetime.timedelta(seconds=60)
        day_cutoff = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= min_cutoff:
                per_min += 1
            if ts >= day_cutoff:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(raindrop_id, str) or not raindrop_id or not re.match(r"^rnd_rdp_[0-9A-Z]{26}$", raindrop_id):
        _log(None, "error", "VALIDATION_ERROR", "raindrop_id invalid")
        return _err("VALIDATION_ERROR", "raindrop_id is missing or invalid", field="raindrop_id")

    raindrops = _load("raindrops.json")
    if not isinstance(raindrops, list):
        raindrops = []
    idx = next((i for i, x in enumerate(raindrops) if x.get("id") == raindrop_id), None)
    if idx is None:
        _log(None, "not_found", "NOT_FOUND", "raindrop not found")
        return _err("NOT_FOUND", "Raindrop not found")

    r = raindrops[idx]
    if r.get("status") == "deleted":
        _log(r.get("account_id"), "not_found", "NOT_FOUND", "already deleted")
        return _err("NOT_FOUND", "Raindrop not found")
    if r.get("status") == "trashed":
        # already trashed: idempotent return current record
        accounts = _load("accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        acct = next((a for a in accounts if a.get("id") == r.get("account_id") and a.get("status") == "active"), None)
        if not acct:
            acct = next((a for a in accounts if a.get("status") == "active"), None)
        if not acct:
            _log(None, "error", "UNAUTHORIZED", "no active account")
            return _err("UNAUTHORIZED", "Unauthorized")
        account_id = acct.get("id")
        if r.get("account_id") != account_id:
            _log(account_id, "not_found", "NOT_FOUND", "cross-account")
            return _err("NOT_FOUND", "Raindrop not found")

        limit_err = _check_limits(account_id)
        if limit_err:
            _log(account_id, "error", limit_err["error"]["code"], limit_err["error"]["message"])
            return limit_err

        _log(account_id, "ok")
        return {"item": r}

    # status must be active to transition to trashed
    if r.get("status") != "active":
        _log(r.get("account_id"), "error", "INVALID_TRANSITION", "cannot trash")
        return _err("INVALID_TRANSITION", "Raindrop cannot be moved to trash from its current status")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == r.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        acct = next((a for a in accounts if a.get("status") == "active"), None)
    if not acct:
        _log(None, "error", "UNAUTHORIZED", "no active account")
        return _err("UNAUTHORIZED", "Unauthorized")
    account_id = acct.get("id")
    if r.get("account_id") != account_id:
        _log(account_id, "not_found", "NOT_FOUND", "cross-account")
        return _err("NOT_FOUND", "Raindrop not found")

    limit_err = _check_limits(account_id)
    if limit_err:
        _log(account_id, "error", limit_err["error"]["code"], limit_err["error"]["message"])
        return limit_err

    rr = dict(r)
    rr["status"] = "trashed"
    rr["trashed_at"] = now_iso
    rr["collection_id"] = None
    rr["updated_at"] = now_iso
    raindrops[idx] = rr
    _save("raindrops.json", raindrops)

    _log(account_id, "ok")
    return {"item": rr}

def restore_raindrop(raindrop_id, collection_id=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0187000" if __import__("os").path.isdir("./environment_mix/0187000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "restore_raindrop"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_file_candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "request_log.json"]
    usage_file = next((fn for fn in usage_file_candidates if os.path.exists(os.path.join(_DB, fn))), "request_logs.json")
    if not os.path.exists(os.path.join(_DB, usage_file)):
        _save(usage_file, [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _log(account_id, status, error_code=None, detail=None):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "timestamp": now_iso,
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _check_limits(account_id):
        if not account_id:
            return None
        logs = _load(usage_file)
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        min_cutoff = now_dt - datetime.timedelta(seconds=60)
        day_cutoff = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= min_cutoff:
                per_min += 1
            if ts >= day_cutoff:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if not isinstance(raindrop_id, str) or not raindrop_id or not re.match(r"^rnd_rdp_[0-9A-Z]{26}$", raindrop_id):
        _log(None, "error", "VALIDATION_ERROR", "raindrop_id invalid")
        return _err("VALIDATION_ERROR", "raindrop_id is missing or invalid", field="raindrop_id")

    if collection_id is not None:
        if collection_id is not None and (not isinstance(collection_id, str) or not re.match(r"^rnd_col_[0-9A-Z]{26}$", collection_id)):
            _log(None, "error", "VALIDATION_ERROR", "collection_id invalid")
            return _err("VALIDATION_ERROR", "collection_id is invalid", field="collection_id")

    raindrops = _load("raindrops.json")
    if not isinstance(raindrops, list):
        raindrops = []
    idx = next((i for i, x in enumerate(raindrops) if x.get("id") == raindrop_id), None)
    if idx is None:
        _log(None, "not_found", "NOT_FOUND", "raindrop not found")
        return _err("NOT_FOUND", "Raindrop not found")

    r = raindrops[idx]
    if r.get("status") == "deleted":
        _log(r.get("account_id"), "not_found", "NOT_FOUND", "deleted")
        return _err("NOT_FOUND", "Raindrop not found")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == r.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        acct = next((a for a in accounts if a.get("status") == "active"), None)
    if not acct:
        _log(None, "error", "UNAUTHORIZED", "no active account")
        return _err("UNAUTHORIZED", "Unauthorized")
    account_id = acct.get("id")
    if r.get("account_id") != account_id:
        _log(account_id, "not_found", "NOT_FOUND", "cross-account")
        return _err("NOT_FOUND", "Raindrop not found")

    limit_err = _check_limits(account_id)
    if limit_err:
        _log(account_id, "error", limit_err["error"]["code"], limit_err["error"]["message"])
        return limit_err

    if r.get("status") == "active":
        # idempotent "restore": optionally move to specified collection_id or unsorted if explicitly null
        if collection_id is None:
            _log(account_id, "ok")
            return {"item": r}

    if r.get("status") != "trashed" and r.get("status") != "active":
        _log(account_id, "error", "INVALID_TRANSITION", "not restorable")
        return _err("INVALID_TRANSITION", "Raindrop cannot be restored from its current status")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []

    dest_id = None
    if collection_id is not None:
        dest_id = collection_id
        col = next((c for c in collections if c.get("id") == dest_id), None)
        if not col or col.get("account_id") != account_id or col.get("status") != "active":
            _log(account_id, "error", "NOT_FOUND", "destination collection")
            return _err("NOT_FOUND", "Destination collection not found")
    else:
        dest_id = None

    rr = dict(r)
    rr["status"] = "active"
    rr["trashed_at"] = None
    rr["collection_id"] = dest_id
    rr["updated_at"] = now_iso
    raindrops[idx] = rr
    _save("raindrops.json", raindrops)

    _log(account_id, "ok")
    return {"item": rr}
